CREATE OR REPLACE FUNCTION public.organization_permission(_id uuid,_type text,_permission text,_scope uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(auth.uid() IS NOT NULL AND public.current_profile_role()::text=_type AND (public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships m WHERE m.organization_id=_id AND m.organization_type=_type AND m.user_id=auth.uid() AND m.status='ativo' AND _permission=ANY(m.permissions) AND (cardinality(m.scope_ids)=0 OR (_scope IS NOT NULL AND _scope=ANY(m.scope_ids))))),false) $$;
CREATE OR REPLACE FUNCTION public.organization_member(_id uuid,_type text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(auth.uid() IS NOT NULL AND public.current_profile_role()::text=_type AND (public.organization_owner(_id,_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships WHERE organization_id=_id AND organization_type=_type AND user_id=auth.uid() AND status='ativo')),false) $$;
CREATE OR REPLACE FUNCTION public.can_validate_student(_institution uuid,_scope uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(auth.uid() IS NOT NULL AND ((public.is_admin() AND public.current_profile_role() NOT IN ('professor','ies','empresa','colaborador')) OR (_institution IS NOT NULL AND public.organization_permission(_institution,'ies','validar_vinculos',_scope))),false) $$;
CREATE OR REPLACE FUNCTION public.guard_organization_reference() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=NEW.organization_id AND NEW.organization_type='empresa') AND NOT EXISTS(SELECT 1 FROM public.institutions WHERE id=NEW.organization_id AND NEW.organization_type='ies') THEN RAISE EXCEPTION 'Organização inválida'; END IF; RETURN NEW; END $$;
CREATE TRIGGER membership_organization_reference BEFORE INSERT OR UPDATE ON public.organization_memberships FOR EACH ROW EXECUTE FUNCTION public.guard_organization_reference();
CREATE TRIGGER scope_organization_reference BEFORE INSERT OR UPDATE ON public.organization_scopes FOR EACH ROW EXECUTE FUNCTION public.guard_organization_reference();
CREATE OR REPLACE FUNCTION public.guard_profile_namespace() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') AND (NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.profile_role IS DISTINCT FROM OLD.profile_role) THEN RAISE EXCEPTION 'Histórico não pode mudar de perfil'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enrollments_namespace BEFORE UPDATE ON public.enrollments FOR EACH ROW EXECUTE FUNCTION public.guard_profile_namespace();
CREATE TRIGGER certificates_namespace BEFORE UPDATE ON public.certificates FOR EACH ROW EXECUTE FUNCTION public.guard_profile_namespace();
REVOKE ALL ON FUNCTION public.switch_test_profile(public.profile_role),public.institution_indicators(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.switch_test_profile(public.profile_role),public.institution_indicators(uuid) TO authenticated;
CREATE POLICY memberships_management_scope_guard ON public.organization_memberships AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.organization_owner(organization_id,organization_type)=auth.uid() OR EXISTS(SELECT 1 FROM public.organization_memberships actor WHERE actor.user_id=auth.uid() AND actor.organization_id=organization_memberships.organization_id AND actor.organization_type=organization_memberships.organization_type AND actor.status='ativo' AND 'subperfis'=ANY(actor.permissions) AND organization_memberships.permissions <@ actor.permissions AND (cardinality(actor.scope_ids)=0 OR (cardinality(organization_memberships.scope_ids)>0 AND organization_memberships.scope_ids <@ actor.scope_ids))));